import fs from 'node:fs';
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { extractMarkdownConservationUnits } from '/home/vantt/projects/forgentX-p9-w1-d3/scripts/generate-doc-inventory.mjs';
const scratch = '/tmp/fgos-work/w4-suite-fix-brief/';
const target = 'plans/260925-documentation-authority-unification/reports/phase-06/working-identity-registry.json';
const original = fs.readFileSync(target);
const generated = fs.readFileSync(scratch + 'current-registry.json');
const old = JSON.parse(original), next = JSON.parse(generated);
const sha = b => crypto.createHash('sha256').update(b).digest('hex');
const all = r => [...r.units, ...(r.identityGaps || []), ...(r.retiredUnits || [])];
const oldIds = new Set(all(old).map(r => r.claimId)), nextIds = new Set(all(next).map(r => r.claimId));
assert.equal(all(old).length, oldIds.size, 'old claim ids are unique across populations');
assert.equal(all(next).length, nextIds.size, 'new claim ids are unique across populations');
const lost = [...oldIds].filter(id => !nextIds.has(id));
assert.deepEqual(lost, [], 'carry never loses a prior claim id');
const source = 'docs/specs/runner.md';
const current = extractMarkdownConservationUnits(fs.readFileSync(source, 'utf8'));
const registered = next.units.filter(r => r.sourcePath === source);
assert.deepEqual(current.map(r => [r.anchor, r.textDigest]).sort(), registered.map(r => [r.sourceAnchor, r.sourceUnitDigest]).sort());
const head = execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
assert.equal(next.commit, head);
const blob = execFileSync('git', ['rev-parse', `${head}:${source}`], { encoding: 'utf8' }).trim();
const doc = next.documents.find(r => r.path === source);
assert.equal(doc.blobSha, blob);
assert.equal(doc.sourceDigest, sha(fs.readFileSync(source)));
const oldMap = new Map(old.units.filter(r => r.sourcePath === source).map(r => [r.sourceAnchor, r]));
const changed = registered.filter(r => oldMap.get(r.sourceAnchor)?.sourceUnitDigest !== r.sourceUnitDigest).map(r => ({ anchor: r.sourceAnchor, before: oldMap.get(r.sourceAnchor) || null, after: r }));
assert.equal(registered.find(r => r.sourceAnchor === 'business-rules').sourceUnitDigest, 'f182ae334ab9402bcb21c9a4568e96cea5a0fde149656b2722f152dcb16a45e9');
fs.copyFileSync(scratch + 'current-registry.json', target);
assert.deepEqual(fs.readFileSync(target), generated, 'persisted bytes equal native generator output');
const counts = r => Object.fromEntries(['documents', 'units', 'identityGaps', 'retiredUnits', 'retiredDocuments'].map(k => [k, (r[k] || []).length]));
const proof = { inputHead: head, target, generator: 'scripts/generate-doc-inventory.mjs --carry-forward-identity-registry (repo-wide)', oldCommit: old.commit, newCommit: next.commit, beforeSha256: sha(original), afterSha256: sha(generated), beforeBytes: original.length, afterBytes: generated.length, beforeCounts: counts(old), afterCounts: counts(next), carryForward: next.carryForward, oldClaimIds: oldIds.size, newClaimIds: nextIds.size, lostClaimIds: lost, uniqueClaimIds: true, persistedGeneratorByteEquality: true, runner: { source, blob, sourceDigest: doc.sourceDigest, beforeUnits: oldMap.size, afterUnits: registered.length, completeAnchorDigestEquality: true, changed } };
fs.writeFileSync(scratch + 'registry-verification.json', JSON.stringify(proof, null, 2) + '\n');
console.log(JSON.stringify(proof, null, 2));
